      applicationStatus: snapshot.application_status,
      itemsObserved: snapshot.items_seen,
      foldersObserved: snapshot.folders_seen,
      posts,
      inWindowRemovedPosts,
      deferredWindowRemovalPostIds: deferredRows.map((row) => row.post_id),
      folders,
